const obs = phi.observe({ maxElements: 200 });
const grab = (n) => ({ ref: n.ref, role: n.role, label: (n.name || n.text || '').slice(0, 60) });
return { url: obs.url, total: obs.total, nodes: obs.nodes.map(grab) };

const obs = phi.observe({ maxElements: 300 });
const t = phi.text();
const idx = t.indexOf('Size');
return { total: obs.total, textAround: t.slice(Math.max(0, idx - 200), idx + 1200), labels: obs.nodes.filter(n => /size|black|\bM\b/i.test((n.name || n.text || '') + '')).slice(0, 40).map(n => ({ ref: n.ref, role: n.role, label: (n.name || n.text || '').slice(0, 60) })) };

