let obs = phi.observe({ maxElements: 500 });
const btn = obs.nodes.find(n => n.role === 'button' && /^filter/i.test((n.name || n.text || '').trim()));
let clickRes = null;
if (btn) { clickRes = phi.click(btn.ref); phi.sleep(1500); }
const obs2 = phi.observe({ maxElements: 600 });
const interesting = obs2.nodes.filter(n => /black|size|^M$|medium|colour|color/i.test((n.name || n.text || '').slice(0, 60)));
return { btn: btn ? { ref: btn.ref, label: btn.name } : null, clickRes: clickRes ? { url: clickRes.url, changed: clickRes.changed } : null, total2: obs2.total, interesting: interesting.slice(0, 60).map(n => ({ ref: n.ref, role: n.role, label: (n.name || n.text || '').slice(0, 45) })) };

