const obs = phi.observe({ maxElements: 600 });
const sizeBtn = obs.nodes.find(n => n.role === 'button' && /^size$/i.test((n.name || n.text || '').trim()));
const filterBtn = obs.nodes.find(n => n.role === 'button' && /^filter/i.test((n.name || n.text || '').trim()));
let log = { filterBtn: filterBtn ? { ref: filterBtn.ref, label: filterBtn.name } : null, sizeBtn: sizeBtn ? { ref: sizeBtn.ref, label: sizeBtn.name } : null };
let res = null;
if (sizeBtn) {
  try {
    res = phi.click(sizeBtn.ref);
  } catch (e) {
    log.err = String(e).slice(0, 200);
  }
}
phi.sleep(1500);
const obs2 = phi.observe({ maxElements: 800 });
log.after = obs2.nodes.filter(n => /^(XS|S|M|L|XL|XXL|3XL|4XL)$|black|size|color/i.test((n.name || n.text || '').trim().slice(0, 40))).slice(0, 80).map(n => ({ ref: n.ref, role: n.role, label: (n.name || n.text || '').trim().slice(0, 40) }));
log.clickRes = res ? { url: res.url, changed: res.changed } : null;
phi.look();
return log;

