const obs = phi.observe({ maxElements: 900 });
const auth = obs.url;
const links = phi.query('a', { fields: ["href"], limit: 400 });
const prod = links.items.filter(i => /\/products\//.test(i.href || ''));
const cards = phi.query('[data-testid="product-card"], li.product-tile, .product-tile, [class*="productTile"]', { limit: 30 });
const items = cards.items.map(c => (c.text||'').replace(/\s+/g,' ').trim());
const active = (obs.text||'').replace(/\n{2,}/g,'\n');
const idx = active.indexOf('Active Filters');
phi.keep('uniqlo_result', {
  url: auth,
  title: obs.title,
  total: cards.total,
  items: items,
  activeFilters: idx >= 0 ? active.slice(idx, idx+160) : null,
  productLinks: [...new Set(prod.map(p => p.href))].slice(0,10)
});
phi.look();
return { total: cards.total, items, activeFilters: idx>=0 ? active.slice(idx, idx+120) : null };

