const obs = phi.observe({ viewportOnly: true, maxElements: 200 });
const cards = phi.query('[data-testid="product-card"], li.product-tile, .product-tile, [class*="productTile"]', { limit: 30 });
const img = phi.readImage(undefined, "Which filter chips are shown as active (size, color, category), and how many product results are listed on screen? List product names and prices.");
return { url: obs.url, title: obs.title, count: cards.total, names: cards.items.map(c => (c.text||'').replace(/\s+/g,' ').trim().slice(0,80)), img };

